
export interface Branch {
  id: number;
  companyId: number;

  // Automatically generated by the backend.
  // Read-only in the Branch Management UI.
  code: string;

  name: string;
  isHeadOffice: boolean;

  phone: string | null;
  email: string | null;

  addressLine1: string | null;
  addressLine2: string | null;
  city: string | null;
  stateOrProvince: string | null;
  postalCode: string | null;
  countryCode: string | null;

  isActive: boolean;

  /**
   * SQL Server rowversion serialized as Base64 by the API.
   * Required for updates and status changes.
   */
  rowVersion: string;
}

/**
 * Branch Code is generated automatically by the backend.
 * The client must not supply a code when creating a branch.
 */
export interface CreateBranchRequest {
  name: string;
  isHeadOffice: boolean;

  phone: string | null;
  email: string | null;

  addressLine1: string | null;
  addressLine2: string | null;
  city: string | null;
  stateOrProvince: string | null;
  postalCode: string | null;
  countryCode: string | null;
}

/**
 * Branch Code and Head Office status cannot be changed
 * through the Update Branch API.
 */
export interface UpdateBranchRequest {
  name: string;

  phone: string | null;
  email: string | null;

  addressLine1: string | null;
  addressLine2: string | null;
  city: string | null;
  stateOrProvince: string | null;
  postalCode: string | null;
  countryCode: string | null;

  rowVersion: string;
}

export interface ChangeBranchStatusRequest {
  rowVersion: string;
}